#include <algorithm>
#include <functional>
#include <iostream>
#include <ranges>
#include <vector>
using namespace std;

int main() {
    vector<int> v = {1, 2, 3, 4, 5, 6, 7, 8};
    auto result = v | views::filter([](int x) { return x % 2 == 0; })
                    | views::transform([](int x) { return x * x; });
    for (int x : result) {
        cout << x << " ";
    }
    cout << endl;
    ranges::sort(v, greater<>());
    cout << v[0] << endl;
    return 0;
}

#include <iostream>
#include <ranges>
using namespace std;

int main() {
    for (int x : views::iota(1) | views::take(5)) {
        cout << x << " ";
    }
    cout << endl;
    return 0;
}

